-- Immutable terminal references and durable transfer obligation; never a second task journal.
CREATE UNIQUE INDEX ux_work_items_terminal_reference ON work_items(work_id,state,state_version);
CREATE UNIQUE INDEX ux_distribution_receipts_result_owner ON distribution_receipts(environment,central_work_id,customer_id,logical_agent_id,central_conversation_id,receipt_id,local_work_id);
CREATE TABLE distribution_results (
 export_id TEXT PRIMARY KEY NOT NULL, upload_id TEXT NOT NULL UNIQUE,
 environment TEXT NOT NULL CHECK(environment='development'), central_work_id TEXT NOT NULL, customer_id TEXT NOT NULL, logical_agent_id TEXT NOT NULL, central_conversation_id TEXT NOT NULL, receipt_id TEXT NOT NULL, local_work_id TEXT NOT NULL UNIQUE,
 work_state TEXT NOT NULL CHECK(work_state IN ('completed','failed','cancelled','interrupted')), state_version INTEGER NOT NULL CHECK(state_version>0), terminal_reason TEXT NOT NULL, terminal_at TEXT NOT NULL CHECK(length(terminal_at)=27 AND terminal_at GLOB '????-??-??T??:??:??.??????Z'),
 terminal_event_id TEXT NOT NULL UNIQUE, assistant_message_id TEXT UNIQUE, native_content_sha256 TEXT,
 snapshot_version INTEGER NOT NULL DEFAULT 1 CHECK(snapshot_version=1), content_version INTEGER NOT NULL DEFAULT 1 CHECK(content_version=1), export_revision TEXT NOT NULL DEFAULT '1' CHECK(export_revision='1'),
 metadata_canonical TEXT NOT NULL CHECK(json_valid(metadata_canonical) AND length(CAST(metadata_canonical AS BLOB))<=16384 AND json_type(metadata_canonical,'$.content') IS NULL),
 wire_content_sha256 TEXT NOT NULL CHECK(length(wire_content_sha256)=64 AND wire_content_sha256 NOT GLOB '*[^0-9a-f]*'), export_digest TEXT NOT NULL CHECK(length(export_digest)=64 AND export_digest NOT GLOB '*[^0-9a-f]*'),
 notice_content_canonical TEXT CHECK(notice_content_canonical IS NULL OR json_valid(notice_content_canonical) AND length(CAST(notice_content_canonical AS BLOB))<=4096),
 last_transfer_outcome TEXT NOT NULL DEFAULT 'not_attempted' CHECK(last_transfer_outcome IN ('not_attempted','uncertain','held','accepted')),
 transfer_state TEXT NOT NULL DEFAULT 'pending' CHECK(transfer_state IN ('pending','accepted','quarantined')),
 acceptance_id TEXT, outbox_source_id TEXT, accepted_at TEXT, acceptance_body TEXT CHECK(acceptance_body IS NULL OR json_valid(acceptance_body) AND length(CAST(acceptance_body AS BLOB))<=16384),
 UNIQUE(environment,central_work_id),
 CHECK(length(export_id)=36 AND substr(export_id,15,1)='7' AND substr(export_id,20,1) IN ('8','9','a','b') AND length(replace(export_id,'-',''))=32 AND replace(export_id,'-','') NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(upload_id)=36 AND substr(upload_id,15,1)='4' AND substr(upload_id,20,1) IN ('8','9','a','b') AND length(replace(upload_id,'-',''))=32 AND replace(upload_id,'-','') NOT GLOB '*[^0-9a-f]*'),
 CHECK(work_state='completed' AND assistant_message_id IS NOT NULL AND native_content_sha256 IS NOT NULL AND notice_content_canonical IS NULL OR work_state<>'completed' AND assistant_message_id IS NULL AND native_content_sha256 IS NULL AND notice_content_canonical IS NOT NULL),
 CHECK(native_content_sha256 IS NULL OR length(native_content_sha256)=64 AND native_content_sha256 NOT GLOB '*[^0-9a-f]*'),
 CHECK(work_state='completed' AND terminal_reason IN ('answered','refused') OR work_state='failed' AND terminal_reason IN ('context_limit','model_attempts_exhausted','agent_loop_limit','tool_calls_limit','provider_failure','invalid_model_output','internal_failure') OR work_state='cancelled' AND terminal_reason IN ('user_request','graceful_shutdown') OR work_state='interrupted' AND terminal_reason IN ('runtime_ownership_lost','provider_outcome_unknown','tool_interrupted_before_dispatch','tool_outcome_unknown','cleanup_unconfirmed')),
 CHECK(acceptance_id IS NULL OR length(acceptance_id)=36 AND substr(acceptance_id,15,1)='4' AND substr(acceptance_id,20,1) IN ('8','9','a','b') AND replace(acceptance_id,'-','') NOT GLOB '*[^0-9a-f]*'),
 CHECK(outbox_source_id IS NULL OR length(outbox_source_id)=36 AND substr(outbox_source_id,15,1)='4' AND substr(outbox_source_id,20,1) IN ('8','9','a','b') AND replace(outbox_source_id,'-','') NOT GLOB '*[^0-9a-f]*'),
 CHECK(accepted_at IS NULL OR length(accepted_at)=27 AND accepted_at GLOB '????-??-??T??:??:??.??????Z'),
 CHECK(json_extract(metadata_canonical,'$.export_id')=export_id AND json_extract(metadata_canonical,'$.work_id')=central_work_id AND json_extract(metadata_canonical,'$.customer_id')=customer_id AND json_extract(metadata_canonical,'$.logical_agent_id')=logical_agent_id AND json_extract(metadata_canonical,'$.conversation_id')=central_conversation_id AND json_extract(metadata_canonical,'$.receipt_id')=receipt_id AND json_extract(metadata_canonical,'$.local_work_id')=local_work_id AND json_extract(metadata_canonical,'$.work_state')=work_state AND json_extract(metadata_canonical,'$.work_state_revision')=CAST(state_version AS TEXT) AND json_extract(metadata_canonical,'$.content_sha256')=wire_content_sha256 AND json_extract(metadata_canonical,'$.terminal_reason')=terminal_reason AND json_extract(metadata_canonical,'$.completed_at')=terminal_at AND json_extract(metadata_canonical,'$.local_message_id') IS assistant_message_id),
 CHECK(acceptance_body IS NULL OR json_extract(acceptance_body,'$.work_id')=central_work_id AND json_extract(acceptance_body,'$.export_id')=export_id AND json_extract(acceptance_body,'$.export_digest')=export_digest AND json_extract(acceptance_body,'$.export_revision')='1' AND json_extract(acceptance_body,'$.acceptance_id')=acceptance_id AND json_extract(acceptance_body,'$.outbox_source_id')=outbox_source_id AND json_extract(acceptance_body,'$.accepted_at')=accepted_at),
 CHECK(transfer_state='accepted' AND last_transfer_outcome='accepted' AND acceptance_id IS NOT NULL AND outbox_source_id IS NOT NULL AND accepted_at IS NOT NULL AND acceptance_body IS NOT NULL OR transfer_state<>'accepted' AND acceptance_id IS NULL AND outbox_source_id IS NULL AND accepted_at IS NULL AND acceptance_body IS NULL),
 FOREIGN KEY(environment,central_work_id,customer_id,logical_agent_id,central_conversation_id,receipt_id,local_work_id) REFERENCES distribution_receipts(environment,central_work_id,customer_id,logical_agent_id,central_conversation_id,receipt_id,local_work_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY(local_work_id,work_state,state_version) REFERENCES work_items(work_id,state,state_version) ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(assistant_message_id) REFERENCES messages(message_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY(terminal_event_id) REFERENCES journal_events(event_id) ON DELETE RESTRICT ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED
) STRICT, WITHOUT ROWID;
CREATE INDEX ix_distribution_results_pending ON distribution_results(transfer_state,central_work_id);
CREATE TRIGGER distribution_terminal_export_guard BEFORE UPDATE OF state,state_version ON work_items
WHEN NEW.state IN ('completed','failed','cancelled','interrupted') AND EXISTS(SELECT 1 FROM distribution_receipts WHERE local_work_id=NEW.work_id)
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM distribution_results WHERE local_work_id=NEW.work_id AND work_state=NEW.state AND state_version=NEW.state_version) THEN RAISE(ABORT,'missing_result_export') END;
END;
CREATE TRIGGER distribution_result_immutable BEFORE UPDATE ON distribution_results
WHEN OLD.transfer_state='accepted' OR NEW.export_id<>OLD.export_id OR NEW.upload_id<>OLD.upload_id OR NEW.environment<>OLD.environment OR NEW.central_work_id<>OLD.central_work_id OR NEW.customer_id<>OLD.customer_id OR NEW.logical_agent_id<>OLD.logical_agent_id OR NEW.central_conversation_id<>OLD.central_conversation_id OR NEW.receipt_id<>OLD.receipt_id OR NEW.local_work_id<>OLD.local_work_id OR NEW.work_state<>OLD.work_state OR NEW.state_version<>OLD.state_version OR NEW.terminal_reason<>OLD.terminal_reason OR NEW.terminal_at<>OLD.terminal_at OR NEW.terminal_event_id<>OLD.terminal_event_id OR NEW.assistant_message_id IS NOT OLD.assistant_message_id OR NEW.native_content_sha256 IS NOT OLD.native_content_sha256 OR NEW.snapshot_version<>OLD.snapshot_version OR NEW.content_version<>OLD.content_version OR NEW.export_revision<>OLD.export_revision OR NEW.metadata_canonical<>OLD.metadata_canonical OR NEW.wire_content_sha256<>OLD.wire_content_sha256 OR NEW.export_digest<>OLD.export_digest OR NEW.notice_content_canonical IS NOT OLD.notice_content_canonical
BEGIN SELECT RAISE(ABORT,'immutable_result'); END;
CREATE TRIGGER distribution_result_delete_guard BEFORE DELETE ON distribution_results BEGIN SELECT RAISE(ABORT,'immutable_result'); END;
CREATE TRIGGER distribution_result_message_update_guard BEFORE UPDATE ON messages WHEN EXISTS(SELECT 1 FROM distribution_results WHERE assistant_message_id=OLD.message_id) BEGIN SELECT RAISE(ABORT,'immutable_result_content'); END;
CREATE TRIGGER distribution_result_message_delete_guard BEFORE DELETE ON messages WHEN EXISTS(SELECT 1 FROM distribution_results WHERE assistant_message_id=OLD.message_id) BEGIN SELECT RAISE(ABORT,'immutable_result_content'); END;
